  if (names.length <= 1) return names.join('');
  if (names.length <= 10) return names.slice(0, -1).join(', ') + ', and ' + names[names.length - 1];
  return names.slice(0, 7).join(', ') + ', et al.';
}
const ieeeName = (a) => initials(a.given) + (initials(a.given) ? ' ' : '') + a.family;
