    const who = isGrey && src.organisation ? src.organisation : joinMla(authors.map(mlaName));
    if (isGrey) return `${who}. ${title}. ${src.publisher ? src.publisher + ', ' : ''}${year}.${doi ? ' ' + doi + '.' : ''}`.replace(/\s+/g, ' ').replace(/\.\./g, '.').trim();
